import json

def accept(raw, context):
    wire = json.loads(raw)
    citations = []
    for citation in wire['evidence']:
        record = context[citation['reference']]
        citations.append({'source': citation['source'], 'quote': citation['quote'], 'source_timestamp': record['IngestedAt']})
    return {'summary': wire['summary'], 'evidence': citations}

def display(output):
    return output['summary']

