def normalize_room(record):
    if type(record['room_id']) is not str or not record['room_id'].strip():
        raise ValueError('room identity required')
    return {'room_id': record['room_id'], 'capacity': int(record['capacity'])}

def select_cancellation(reservations, room_id):
    return [reservation['reservation_id'] for reservation in reservations if reservation['room_id'] == room_id and reservation['cancelled']]

