def normalize_completion(record):
    if type(record['learner_id']) is not str or not record['learner_id'].strip():
        raise ValueError('learner identity required')
    return {'learner_id': record['learner_id'], 'completed': record['completed'] is True}

def award_preview(completion):
    return {'learner_id': completion['learner_id'], 'eligible': completion['completed']}
